def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp = [h[1] for h in history]
    opp_d = 0
    for a in opp:
        if a == 'D':
            opp_d += 1

    if n >= 5 and opp_d / n > 0.5:
        if rng.random() < 0.9:
            return 'D'
        return 'C'

    if opp_d == 0:
        if n >= 10 and n % 10 == 0 and n < 90:
            return 'D'
        return 'C'

    last_my, last_opp = history[-1]
    if last_opp == 'D':
        if opp_d <= 2:
            return 'C'
        return 'D'
    else:
        if last_my == 'D':
            return 'C'
        return 'C'
